from copy import deepcopy
from six import raise_from
from taf.internal.managedobject import ManagedObject
from taf.internal.rfsw.ssh_connection import RFSWSSHConnection
from taf.internal.rfsw.ssh_connection.exception import ConnectionFail
from taf.internal.rfsw.ssh_connection import (SSHHop, ExtraSSHServiceHop, LXCSSHHop, RUService)
from taf.ul.rfsw.ssh import features
from taf.ul.rfsw.ssh.exception import RUConnectionFail, InsufficientCredentialRelevantInfo


class RU(ManagedObject):

    @classmethod
    def create(cls, hop_info_list, ru_service_info, ru_name, fh_interface):
        ru_service_config = RUService.create(**ru_service_info)

        hop_config_list = []
        for hop in hop_info_list:
            if hop.get('new_port'):
                hop_config_list.append(ExtraSSHServiceHop.create(**hop))
            elif hop.get('container_id'):
                hop_config_list.append(LXCSSHHop.create(**hop))
            else:
                hop_config_list.append(SSHHop.create(**hop))

        return RU(hop_config_list, ru_service_config, ru_name, fh_interface)

    def __init__(self, hops_config, service_config, ru_name, fh_interface, connections=None, users=None):
        super(RU, self).__init__()
        self._hops_config = hops_config
        self._service_config = service_config
        self._ru_name = ru_name
        self._fh_interface = fh_interface
        self._connections = connections or []
        self._users = users or []

    @property
    def name(self):
        return self._ru_name

    @property
    def username(self):
        return self._service_config.username

    @property
    def user_vs_connection(self):
        return dict(zip(self._users, self._connections))

    def create_next_ru(self, ru_service_info, ru_name, fh_interface):
        ru_service_config = RUService.create(**ru_service_info)
        new_hops_config = []
        for hop in self._hops_config:
            if type(hop) is SSHHop:
                new_hops_config.append(hop)
            elif type(hop) is ExtraSSHServiceHop:
                new_hops_config.append(SSHHop(hop.host, hop.username, hop.password, port=hop.new_port))
            elif type(hop) is LXCSSHHop:
                new_hops_config.append(SSHHop(hop.host, hop.username, hop.password, port=hop.port))
            else:
                pass  # will never enter
        new_ru = RU(new_hops_config, ru_service_config, ru_name, fh_interface, self._connections, self._users)
        self.add_prerequisite(new_ru)
        return new_ru

    def setup_connection(self, username=None):
        """
        setup connection to ru

        :param username: Optional[str], None by default, when the username is None,
        connection with parameters configured when initializing this ru will be setup.
        when username is set, connection with this username will be setup even different from the initialized username
        :return: RFSWSSHConnection
        """

        if not self._connections:
            connection = self._prepare_first_connection(username)
        else:
            original_connection = self._connections[0]
            if not username:
                return original_connection

            if username in self._users:
                return self.user_vs_connection[username]
            connection = original_connection.create_additional_connection(ru_username=username)

        try:
            connection.setup()
            self._connections.append(connection)
            self._users.append(username)
            return connection
        except ConnectionFail as exp:
            raise_from(RUConnectionFail(), exp)

    def _prepare_first_connection(self, username):
        new_service_config = deepcopy(self._service_config)
        if username:
            new_service_config.username = username
        else:
            if not new_service_config.username:
                raise InsufficientCredentialRelevantInfo("service user name is missing")

        return RFSWSSHConnection(self._hops_config,
                                 new_service_config,
                                 ru_name=self._ru_name,
                                 fh_interface=self._fh_interface)

    def teardown_connections(self):
        if self._connections:
            self._connections[0].teardown()
            del self._connections[:]
            del self._users[:]

    def get_connection(self, username=None):
        if not username and not self._connections:
            return None
        if not username:
            return self._connections[0]
        return self.user_vs_connection.get(username)

    def retrieve_tx_power(self, connection, sudo_enabled=False, process_number=None):
        retrieve_tx_power = features.RetrieveTxPower(self._ru_name,
                                                     connection,
                                                     sudo_enabled=sudo_enabled,
                                                     processes=process_number)
        return retrieve_tx_power.run()

    def release(self):
        self.teardown_connections()
